typedef unsigned int u_int;

class vector3d
{
public:
  float x;
  float y;
  float z;
  vector3d () {}
  vector3d (float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}
  vector3d (const vector3d& v) : x(v.x), y(v.y), z(v.z) {}
  vector3d& operator=(const vector3d& v) { x=v.x; y=v.y; z=v.z; return *this; }
};

extern const vector3d ZEROVEC;
class WavePositionHint;
class po
{
public:
  vector3d slow_xform (const vector3d& source_vector) const;
};

class entity
{
  char pad[80];
  po *my_abs_po;
public:
  const po& get_abs_po() const { return *my_abs_po; }
};

class SurfBoardObjectClass { public: char pad[3480]; float air_timer; float GetAirTime(void) { return air_timer; } };
class kellyslater_controller
{
  char pad0[3480];
  float air_timer;
  char pad1[172];
  entity *my_board;
public:
  SurfBoardObjectClass & get_board_controller(void) { return *(SurfBoardObjectClass *)this; }
  entity * GetBoard(void) { return my_board; }
};

struct spray_params_t
{
  char pad[3264];
  float airdrops_interval;
};

void ks_fx_add_splash (u_int fxindex, const vector3d& pos, float size);

static float airdrops_time = 0.2f;
static float airdrops_interval_time = 0.05f;

class trail
{
  char pad[0xcd74];
  kellyslater_controller* my_owner;
  spray_params_t *my_spray;
public:
  void add_point (vector3d *pointa, vector3d *center, vector3d *pointb, float vela, float velb, WavePositionHint *hint, bool dummy);
  void board_update_air (float dt);
};

void trail::board_update_air (float dt)
{
  entity *board_ptr = my_owner->GetBoard();

  vector3d pt(ZEROVEC);
  add_point (&pt, &pt, &pt, 0, 0, 0, true);

  if (my_owner->get_board_controller ().GetAirTime () < airdrops_time)
  {
    my_spray->airdrops_interval += dt;

    static float last_splash = 0.0f;
    last_splash += dt;
    if(last_splash < 1.0f/60.0f)
      return;

    last_splash = 0.0f;

    if (my_spray->airdrops_interval > airdrops_interval_time)
    {
      vector3d pos;

      pos = board_ptr->get_abs_po().slow_xform (vector3d (0, 0, -0.2));

      ks_fx_add_splash(11, pos, 1.0f);
    }
  }
  else
    my_spray->airdrops_interval = 0;
}
